import { analyzeRequirement, baseSkills, getTaskProfile, isMeaningfulRequirementValue, requirementSteps, selectDailyTasks, starterLayers, taskChecks, tasks, type RequirementFieldName, type StarterField, type StarterLayer, type Task, type TrainingMode } from "./data";
