const blankActionPlan:ActionPlan={candidateActions:"",nextBestAction:"",selectedTool:"",informationGain:50,expectedObservation:"",cost:"low",risk:"medium",fallback:"",scopeGoal:"",proposedFiles:"",impactAnalysis:"",excludedChanges:"",contextBudget:"",approvalDecision:""};
