const blankReview:ReviewDecision={decision:"",scopeDecision:"",riskLevel:"P1",issues:"",rationale:"",revisionRequest:"",understanding:"",rollback:"",architectureDriftDetected:false,impactApproved:false,finalApproval:false,reviewCapacity:180,trustBefore:50,trustAfter:30,suggestionDecisions:{}};
const toolNames:Record<string,string>={code:"代码",logs:"日志",network:"网络",api:"API",sql:"SQL",db:"数据库",docker:"Docker",env:"环境",search:"搜索",runtime:"运行态",diff:"Diff",tests:"验收"};
const initialDailyTasks=selectDailyTasks([],baseSkills);
const initialTask=initialDailyTasks[0];
const initialFiles=initialTask.files?.length?initialTask.files:[{path:initialTask.contextTitle,language:"text",content:initialTask.context}];
const ACTIVE_TASK_KEY="forge-active-requirement-v1";
const draftKey=(task:Task)=>`forge-requirement-draft-v1:${task.variantId??task.id}`;
